window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7529f3701f96f69e"]={"versions": [{"id": "FIG-7529f3701f96f69e", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> C++14-Code-Listing / API-Nutzungsbeispiel (Interaktionsmuster).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Spezifiziert das clientseitige Zugriffsmuster der AUTOSAR Adaptive Platform (AP Release 17-10 / R1.2.0) innerhalb des Communication Management (<code>ara::com</code>). Es demonstriert die typsichere Auswertung von komplexen Datentypen mit optionalen Elementen (<code>ara::core::Optional&lt;T&gt;</code>) beim synchronen/asynchronen Empfang über Service-Interfaces (Method-Pattern via <code>ara::com::Future</code>).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>ara::com::BatteryStateProxy</code>:</strong> Generierter Service-Proxy (Client-Schnittstelle) zur Interaktion mit dem zugrundeliegenden Service-Skeleton über die Middleware (z. B. SOME/IP oder IPC).\n</li><li><strong><code>ara::com::HandleType</code> (<code>handle</code>):</strong> Instanz-Deskriptor, der via Service Discovery (<code>FindService</code>) akquiriert wurde und an den Proxy-Konstruktor übergeben wird.\n</li><li><strong><code>ara::com::Future&lt;BatteryState&gt;</code>:</strong> Template-Klasse zur Handhabung asynchroner Methoden-Rückgabewerte (<code>GetBatteryState()</code>).\n</li><li><strong><code>BatteryState</code>:</strong> Komplexe Datenstruktur (Payload), bestehend aus obligatorischen und optionalen Membern:\n<ul class=\"fig-list\"><li><code>current</code>: Optionales Element, typisiert als <code>ara::core::Optional&lt;CurrentType&gt;</code>.\n</li><li><code>health</code>: Optionales Element, typisiert als <code>ara::core::Optional&lt;HealthType&gt;</code>.\n</li></ul>\n</li><li><strong>Schnittstellenmethoden &amp; Operatoren von <code>ara::core::Optional</code>:</strong>\n<ul class=\"fig-list\"><li><code>explicit operator bool()</code>: Kontextuelle Konvertierung zur Präsenzprüfung.\n</li><li><code>operator*()</code>: Dereferenzierung zum direkten Lesezugriff auf den umschlossenen Rohwert (ohne Exception-Check).\n</li><li><code>has_value()</code>: Explizite Member-Funktion zur Präsenzprüfung.\n</li><li><code>value()</code>: Lesezugriff auf den umschlossenen Wert (mit Validitätsprüfung).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Proxy-Instanziierung (Z. 6):</strong> Bindung der Proxy-Instanz <code>bms_service</code> an den Zielservice via <code>handle</code>.\n</li><li><strong>Asynchroner Service-Aufruf (Z. 7):</strong> Aufruf der Service-Methode <code>bms_service.GetBatteryState()</code>. Übergibt den Methodenaufruf an die Middleware-Serialisierung und liefert unmittelbar ein <code>stateFuture</code> zurück.\n</li><li><strong>Synchronisationsbarriere (Z. 9):</strong> <code>stateFuture.get()</code> blockiert den aufrufenden Thread, bis die Serialisierung/Netzwerkantwort des Skeletons eintrifft und deserialisiert vorliegt.\n</li><li><strong>Präsenzprüfung &amp; Zugriff – Pfad 1 (Pointer-Semantik, Z. 12–17):</strong>\n<ul class=\"fig-list\"><li>Prüfung via boolesche Auswertung: <code>if (state.current)</code>.\n</li><li>Bei gesetztem Wert: Zugriff über Dereferenzierung <code>*state.current</code> und Evaluierung gegen <code>MAX_CURRENT</code>.\n</li></ul>\n</li><li><strong>Präsenzprüfung &amp; Zugriff – Pfad 2 (Methoden-Semantik, Z. 20–25):</strong>\n<ul class=\"fig-list\"><li>Prüfung via Member-Methode: <code>if (state.health.has_value())</code>.\n</li><li>Bei gesetztem Wert: Zugriff über Getter-Methode <code>state.health.value()</code> und Evaluierung gegen <code>BAD_HEALTH</code>.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Defensive Absence-Prüfung:</strong> Der Zugriff auf optionale Elemente ohne vorherige Prüfung (<code>has_value()</code> oder <code>operator bool</code>) ist strikt verboten:\n<ul class=\"fig-list\"><li><code>*state.member</code> führt bei leerem <code>Optional</code> zu <em>Undefined Behavior</em>.\n</li><li><code>state.member.value()</code> wirft bei leerem <code>Optional</code> eine Exception (<code>bad_optional_access</code>), was in ASIL-relevanten Adaptive-Applikationen zum Prozessabbruch (Abnormal Termination durch den Execution Manager) führen kann.\n</li></ul>\n</li><li><strong>Wire-Format &amp; Bandbreiten-Optimierung:</strong> Auf SOME/IP-Ebene (und im E2E/Serializer) werden optionale Elemente über Bitmasken/TLV-Kodierung abgebildet. Nicht gesetzte Felder (wie im Skeleton-Kontext für <code>health</code> gezeigt) werden netzwerkseitig nicht übertragen; der Empfänger-Deserializer instanziiert das Feld automatisch im Zustand <code>nullopt</code>.\n</li><li><strong>Echtzeit- &amp; Blocking-Restriktion:</strong> Das dargestellte synchrone Blockieren via <code>stateFuture.get()</code> blockiert den Thread bis zum Timeout oder Response-Eingang. Für harte Echtzeitanforderungen in AUTOSAR AP ist vorzugsweise das asynchrone Continuation-Muster (<code>stateFuture.then(...)</code>) oder nicht-blockierendes Polling (<code>wait_for(0)</code>) einzusetzen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8c0db0b447cd8ad8", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> C++-Code-Listing (Fragment / Rumpf).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Bildet lediglich das Dateiende eines Codebeispiels ab, bestehend aus Zeilennummerierung und schließenden geschweiften Klammern ohne sichtbare funktionale Logik oder Schnittstellenaufrufe.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Das Listing enthält keine Schnittstellen, Entitäten oder Komponentenbezeichner, sondern ausschließlich schließende Syntaxelemente (Klammern der Zeilen 24, 25 und 26).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Es ist kein dynamisches Verhalten oder Ablauf sichtbar; dargestellt sind ausschließlich die Zeilen 24 bis 26 mit schließenden geschweiften Klammern.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Durch das Fehlen des Deklarations- und Verarbeitungsblocks besitzt das Listing im sichtbaren Bereich keine eigenständige normative Relevanz für die API-Nutzung.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-7529f3701f96f69e", "to": "FIG-8c0db0b447cd8ad8", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Code-Listing (Zeilen 1 bis 23): Der gesamte Implementierungscode (Include/Namespace, <code>main()</code>, Proxy-Instanziierung <code>BatteryStateProxy</code>, Service-Aufruf via <code>GetBatteryState()</code>, Future-Synchronisation sowie die beiden Prüfpfade für <code>state.current</code> und <code>state.health.has_value()</code>) ist abgeschnitten; im Bild verbleiben lediglich die schließenden geschweiften Klammern der Zeilen 24 bis 26.\n</li></ul>"}]};
